  fn match_char(p: Char, c: Char) -> Bool {
    if p == '\\' {
      return c == p;
    }
    return p == '?' || p == c;
  }

  fn match_segment(pattern: String, s: String) -> Bool {
    let mut i = 0;
    for p in pattern.chars() {
      if p == '*' {
        if i == s.len() {
          return true;
        }
        i += 1;
      } else if i >= s.len() || !match_char(p, s.chars().nth(i).unwrap()) {
        return false;
      } else {
        i += 1;
      }
    }
    return i == s.len();
  }

  return match_segment(pattern, s);
}

